              <button key={hint} onClick={()=>setIdeaInput(hint+" — ")} style={{padding:"4px 10px",borderRadius:4,border:"1px solid "+C.border,background:C.cream,fontSize:10,fontFamily:"system-ui",cursor:"pointer",color:"#666"}}>+ {hint}</button>
